{"nodes":[{"id":"start_0","type":"start","meta":{"position":{"x":180,"y":89.5}},"data":{"title":"Start","outputs":{"type":"object","properties":{},"required":[]}}},{"id":"code_time","type":"code","meta":{"position":{"x":640,"y":0}},"data":{"title":"计算时间区间","inputsValues":{},"script":{"language":"xlang","content":"<c:script> 
 import java.time.Instant; 
 import java.time.ZoneId; 
 import java.time.LocalDateTime; 
 import java.time.format.DateTimeFormatter; 
 import io.nop.commons.util.DateHelper; 

 let now = DateHelper.currentTimeMillis(); 
 let endTime = now - 60000; 
 let startTime = endTime - 60000; 

 // Convert to LocalDateTime and format 
 let endDateTime = Instant.ofEpochMilli(endTime).atZone(ZoneId.systemDefault()).toLocalDateTime(); 
 let startDateTime = Instant.ofEpochMilli(startTime).atZone(ZoneId.systemDefault()).toLocalDateTime(); 

 return { 
 "kssj": DateHelper.DATETIME_FORMATTER.format(startDateTime), 
 "jssj": DateHelper.DATETIME_FORMATTER.format(endDateTime) 
 }; 
</c:script>"},"outputs":{"type":"object","properties":{"kssj":{"type":"string"},"jssj":{"type":"string"}}},"inputs":{"type":"object","properties":{}}}},{"id":"code_http","type":"code","meta":{"position":{"x":1100,"y":0}},"data":{"title":"调用两客一危接口","inputsValues":{"kssj":{"type":"ref","content":["code_time","kssj"],"extra":{"index":0}},"jssj":{"type":"ref","content":["code_time","jssj"],"extra":{"index":1}}},"script":{"language":"xlang","content":"<c:script> 
 import cn.hutool.http.HttpRequest; 
 import cn.hutool.http.HttpResponse; 
 import java.util.HashMap; 
 import java.util.Map; 
 import org.noear.snack.ONode; 

 let baseUrl = 'http://localhost:12009/jkfw/region/getyzlkywgps'; 

 // 创建请求头Map 
 let headers = new HashMap(); 
 headers.put('token', '8914dfc5-beca-45c9-918c-01791b9c8b62'); 
 headers.put('Content-Type', 'application/json'); 

 // 创建请求对象 
 let request = HttpRequest.get(baseUrl); 

 // 使用addHeaders批量添加请求头 
 request = request.addHeaders(headers); 

 // 创建参数 Map 
 let params = new HashMap(); 
 params.put('kssj', kssj); 
 params.put('jssj', jssj); 
 params.put('size', '10'); 
 // 转换为 JSON 
 let jsonBody = ONode.load(params).toJson(); 
 // 添加参数 
 request = request.body(jsonBody); 


 // 设置超时 
 request = request.timeout(30000); 

 // 执行请求 
 let response = request.execute(); 

 let responseBody = response.body(); 

 if (!response.isOk()) { 
 logError('HTTP请求失败，状态码: {}', response.getStatus()); 
 } 

 return { 
 "response": responseBody 
 }; 
